$rows=db_all("SELECT h.*,t.ho_ten FROM hop_dong h JOIN tai_khoan t ON t.id=h.tai_khoan_id WHERE $where ORDER BY h.ngay_lap DESC LIMIT 200");table_start(['Hợp đồng','Khách / VIN','Giá trị','Trạng thái','']);foreach($rows as$r){echo '<tr><td>'.e($r['so_hop_dong']).'</td><td>'.e($r['ho_ten']).'<br>'.e($r['so_khung_vin']).'</td><td>'.e(money($r['tong_gia_tri'])).'</td><td>'.badge($r['trang_thai_hd']).'</td><td>';if(!$r['nhan_vien_id']){token_form();field('id','',$r['so_hop_dong'],'hidden');if($me['quyen']==='ADMIN')select_field('nhan_vien_id','Nhân viên',choices("SELECT id,ho_ten FROM tai_khoan WHERE quyen='NHAN_VIEN' AND trang_thai='HOAT_DONG'",'id','ho_ten'),'',true);echo '<button class="small" name="action" value="claim">Tiếp nhận</button></form>';}else echo '<a href="'.e(url('nhan_vien/'.$mode.'.php?id='.$r['so_hop_dong'])).'">Mở</a>';echo '</td></tr>';}table_end();
if($id){$h=contract($id,$me);$net=money_total($id);$customer=db_one('SELECT ho_ten,email,so_dien_thoai,dia_chi FROM tai_khoan WHERE id=?',[$h['tai_khoan_id']]);echo '<section class="panel"><h2>Hợp đồng '.e($id).'</h2><p>'.e(implode(' · ',array_filter($customer))).'</p><p>VIN: '.e($h['so_khung_vin']).' · '.badge($h['trang_thai_hd']).'</p><p>Giá trị: '.e(money($h['tong_gia_tri'])).' · Đã trả ròng: '.e(money($net)).' · Còn thiếu: '.e(money(max(0,(int)$h['tong_gia_tri']-$net))).'</p><div class="actions">';foreach(['hop_dong'=>'Hồ sơ hợp đồng','thanh_toan'=>'Thu tiền','ban_giao'=>'Bàn giao']as$p=>$t)echo '<a class="button ghost small" href="'.e(url('nhan_vien/'.$p.'.php?id='.$id)).'">'.e($t).'</a>';echo '<button class="ghost no-print" onclick="window.print()">In hợp đồng</button></div>';
token_form();field('id','',$id,'hidden');if($mode==='hop_dong'){field('ngay_ky','Thời điểm ký hợp đồng',$h['ngay_ky']??'','datetime-local');field('tien_do','Tiến độ giao xe',$h['tien_do_giao_xe']??'');echo '<label><input type="checkbox" name="ho_so" value="1" '.($h['ho_so_day_du']?'checked':'').'>Đã kiểm tra đủ hồ sơ</label><button name="action" value="save">Lưu hồ sơ</button>';}
elseif($mode==='thanh_toan'){field('request_key','',new_request_key(),'hidden');field('so_tien','Số tiền thực nhận (đ)',max(0,(int)$h['tong_gia_tri']-$net),'number','min="1" required');select_field('phuong_thuc','Phương thức',['CHUYEN_KHOAN'=>'Chuyển khoản','TIEN_MAT'=>'Tiền mặt'],'CHUYEN_KHOAN',true);field('nguon','Nguồn chứng từ (ngân hàng / quỹ)','','text','required maxlength="100"');field('tham_chieu','Mã chứng từ thực tế','','text','required maxlength="100"');field('ngay_thu','Ngày thu',date('Y-m-d\TH:i'),'datetime-local','required');echo '<label><input type="checkbox" name="confirmed" value="1" required>Tôi đã đối chiếu khoản tiền thực nhận</label><button name="action" value="receipt">Ghi nhận thanh toán</button>';}
else echo '<p>Hệ thống sẽ kiểm tra đủ tiền, ngày ký, hồ sơ và VIN trước khi bàn giao.</p><button name="action" value="handover">Xác nhận đã bàn giao xe</button>';echo '</form></section>';
